let db=load(),view='overview',editing=null,toastTimer,viewHistory=[];
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE));if(v&&v.projects&&v.clients&&v.pricing&&v.leads)return v}catch(e){}return structuredClone(seed)}
function save(){localStorage.setItem(STORAGE,JSON.stringify(db));}
const fmt=n=>n==null||n===''?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:2})+' ₫';
function parseDecimal(v){const raw=String(v??'').trim().replace(/\s/g,'');if(!raw)return '';let s=raw;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:''}
function moneyUnit(value,unit){if(value==null||value==='')return 'Chưa cập nhật';const u=unit||'Theo tháng (VNĐ/tháng)';return u.startsWith('%')?`${Number(value).toLocaleString('vi-VN',{maximumFractionDigits:2})}% lương tháng`:fmt(value)+' · '+u}
function formatAmount(value,unit){if(value==null||value==='')return '—';return String(unit||'').startsWith('%')?Number(value).toLocaleString('vi-VN',{maximumFractionDigits:2})+'%':fmt(value)}
const num=n=>Number(n||0).toLocaleString('vi-VN');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allRegions=()=>[...new Set([...db.projects.map(x=>x.region),...db.clients.map(x=>x.region),...db.pricing.map(x=>x.region),...db.leads.map(x=>x.region)].filter(Boolean))].sort();
const statusPill=s=>{let c='';if(/đang chạy|đang hợp tác|đã chuyển đổi/i.test(s||''))c='';else if(/xác minh|đang tiếp cận|đang đàm phán|cần nghiên cứu/i.test(s||''))c='amber';else if(/tạm dừng|mất/i.test(s||''))c='red';else c='gray';return `<span class="pill ${c}">${esc(s||'Chưa cập nhật')}</span>`};
const regionFilter=(id='regionFilter')=>`<select class="control" id="${id}"><option value="">Tất cả khu vực</option>${allRegions().map(r=>`<option>${esc(r)}</option>`).join('')}</select>`;
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function setView(v){if(v!==view)viewHistory.push(view);view=v;$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(typeof closeMenu==='function')closeMenu();else $('#sidebar').classList.remove('open');const titles={overview:'Tổng quan thị trường',projects:'Dự án & nhân sự',clients:'Hồ sơ khách hàng',pricing:'Lương & phí dịch vụ',opportunities:'Cơ hội tiềm năng',research:'Nghiên cứu thị trường',data:'Excel & dữ liệu',settings:'Cài đặt'};$('#pageTitle').textContent=titles[v];$('#crumb').textContent=v==='overview'?'SALES COMMAND CENTER':'BPO INTELLIGENCE / '+titles[v].toUpperCase();render()}
function render(){const q=($('#globalSearch').value||'').trim().toLowerCase();const c=$('#content');if(view==='overview')c.innerHTML=overview(q);else if(view==='projects')c.innerHTML=projectsPage(q);else if(view==='clients')c.innerHTML=clientsPage(q);else if(view==='pricing')c.innerHTML=pricingPage(q);else if(view==='research')c.innerHTML=researchPage();else if(view==='settings')c.innerHTML=settingsPage();else if(view==='data')c.innerHTML=dataPage();else c.innerHTML=leadsPage(q);$('#backBtn').style.visibility=viewHistory.length?'visible':'hidden';}
function overview(q=''){
const active=db.projects.filter(x=>String(x.status||'').trim()==='Đang chạy');
const needsVerify=db.projects.filter(x=>/xác minh|chưa xác minh|cần nghiên cứu/i.test(String(x.status||'')));
const currentClients=db.clients.filter(x=>x.type==='Khách hàng hiện tại').length;
const prospectClients=db.clients.filter(x=>x.type==='Khách hàng tiềm năng').length;
const roles=new Set(db.projects.flatMap(x=>String(x.positions||'').split(/[,;\n|]+/).map(s=>s.trim()).filter(Boolean))).size;
const leadN=db.leads.filter(x=>!['Đã chuyển đổi','Không phù hợp'].includes(x.status)).length;
const regionCounts=allRegions().map(r=>({r,n:db.projects.filter(p=>String(p.region||'').trim()===r).length,active:active.filter(p=>String(p.region||'').trim()===r).length,verify:needsVerify.filter(p=>String(p.region||'').trim()===r).length})).filter(x=>x.n>0).sort((a,b)=>b.n-a.n);
const max=Math.max(1,...regionCounts.map(x=>x.n));
const recent=[...db.projects.map(x=>({date:x.updated||'',title:x.customer,desc:`${x.region} · ${x.positions} · ${x.status||'Chưa cập nhật'}`,type:'Dự án'})),...db.pricing.map(x=>({date:x.updated||'',title:x.position,desc:`${x.region} · ${x.verified||'Chưa xác minh'}`,type:'Bảng giá'})),...db.leads.map(x=>({date:x.updated||'',title:x.name,desc:`${x.region} · ${x.status}`,type:'Cơ hội'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
return `
<div class="welcome"><div><div class="eyebrow">BPO SALES COMMAND CENTER</div><h2>Biến dữ liệu thị trường thành cơ hội kinh doanh.</h2><p>Theo dõi dự án, nhân sự, mức lương và phí dịch vụ theo từng khu vực — tất cả trong một nơi.</p></div><button class="primary-btn" data-add="project">＋ Thêm dự án</button></div>
<div class="callout dashboard-data-note"><b>Số liệu cập nhật theo dữ liệu đang lưu trên thiết bị.</b> Dữ liệu mới nhập từ Excel sẽ được tính vào tổng khách hàng, dự án và vị trí ngay cả khi trạng thái còn “Cần xác minh”. Chỉ dự án có trạng thái “Đang chạy” mới được tính là đang chạy.</div>
<div class="metric-grid"><div class="metric"><div class="metric-top"><span class="metric-label">Tổng khách hàng</span><span class="metric-icon">▣</span></div><div class="metric-value">${db.clients.length}</div><div class="metric-foot">${currentClients} hiện tại · ${prospectClients} tiềm năng · ${Math.max(0,db.clients.length-currentClients-prospectClients)} nhóm khác</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Tổng dự án</span><span class="metric-icon">▤</span></div><div class="metric-value">${db.projects.length}</div><div class="metric-foot">${active.length} đang chạy · ${needsVerify.length} cần xác minh · tổng nhân sự đang chạy: ${num(active.reduce((a,x)=>a+Number(x.headcount||0),0))}</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Vị trí trong dự án</span><span class="metric-icon">♙</span></div><div class="metric-value">${roles}</div><div class="metric-foot">Số vị trí khác nhau trong toàn bộ danh mục dự án</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Cơ hội đang theo dõi</span><span class="metric-icon">◎</span></div><div class="metric-value">${leadN}</div><div class="metric-foot">Lead chưa chuyển đổi hoặc đóng · ${db.leads.length} tổng cơ hội</div></div></div>
${marketFinder()}
<div class="layout-two"><section class="panel"><div class="panel-head"><div><h3>Dự án theo khu vực</h3><p>Tổng dự án; trạng thái đang chạy và cần xác minh được tách rõ</p></div><button class="text-btn" data-view="projects">Xem dự án →</button></div>${regionCounts.length?`<div class="region-list">${regionCounts.map(x=>`<div class="region-row"><span class="region-name">${esc(x.r)}</span><div class="bar-track"><div class="bar-fill" style="width:${x.n/max*100}%"></div></div><span class="region-count" title="${x.active} đang chạy · ${x.verify} cần xác minh">${x.n}</span></div>`).join('')}</div><p class="cell-sub" style="margin-top:10px">Số bên phải là tổng dự án theo khu vực; rê/chạm để xem số đang chạy và cần xác minh.</p>`:'<div class="empty-hint">Chưa có dự án. Nhập Excel hoặc thêm dự án để xem phân bố theo khu vực.</div>'}</section>
<section class="panel"><div class="panel-head"><div><h3>Cập nhật gần đây</h3><p>Theo dõi những hồ sơ vừa thay đổi</p></div></div>${recent.length?`<div class="activity-list">${recent.map(x=>`<div class="activity"><div class="activity-dot">${x.type==='Dự án'?'▤':x.type==='Bảng giá'?'↗':'◎'}</div><div><b>${esc(x.title)}</b><p>${esc(x.desc)}</p></div><span class="cell-sub">${esc(x.date)}</span></div>`).join('')}</div>`:'<div class="empty-hint">Chưa có hoạt động gần đây.</div>'}</section></div>
<div class="panel"><div class="panel-head"><div><h3>Tín hiệu thị trường từ nguồn công khai</h3><p>Thông tin tham khảo để định hướng survey — không phải báo giá BPO</p></div><button class="text-btn" data-view="research">Nghiên cứu thêm →</button></div><div class="market-stats"><article class="market-stat"><span class="metric-label">Lương tối thiểu vùng I · 2026</span><strong>5,31 triệu ₫</strong><p class="muted">Mức tối thiểu theo tháng; áp dụng từ 01/01/2026, không phải benchmark trung bình.</p><a href="https://baochinhphu.vn/tang-luong-toi-thieu-vung-tu-1-1-2026-102251110175033018.htm" target="_blank" rel="noopener">Báo Chính phủ ↗</a></article><article class="market-stat"><span class="metric-label">Nhu cầu lao động</span><strong>Công nghiệp & dịch vụ</strong><p class="muted">Bản tin GSO 6 tháng 2026: công nghiệp/xây dựng và dịch vụ đều tăng việc làm so với cùng kỳ.</p><a href="https://www.nso.gov.vn/tin-tuc-thong-ke/2026/07/thong-cao-bao-chi-ve-tinh-hinh-lao-dong-viec-lam-quy-ii-va-6-thang-dau-nam-2026/" target="_blank" rel="noopener">GSO ↗</a></article><article class="market-stat"><span class="metric-label">Vị trí phổ thông cần survey</span><strong>Kho · Sản xuất · Vệ sinh</strong><p class="muted">Mở truy vấn tin tuyển dụng công khai theo địa bàn để thu thập lương, ca làm và phụ cấp.</p><a href="https://www.google.com/search?q=tuy%E1%BB%83n+c%C3%B4ng+nh%C3%A2n+kho+v%E1%BB%87+sinh+b%E1%BA%A3o+v%E1%BB%87+Vi%E1%BB%87t+Nam" target="_blank" rel="noopener">Tìm nguồn ↗</a></article></div><p class="market-source">Nguồn công khai được dẫn liên kết để người dùng tự kiểm tra. Mức lương tuyển dụng không đồng nghĩa với phí dịch vụ BPO; các dự án mẫu và số liệu dashboard khác do người dùng nhập, không được giả định là số liệu toàn thị trường.</p></div>
<div class="panel"><div class="panel-head"><div><h3>Việc cần làm để dữ liệu hữu ích hơn</h3><p>Khuyến nghị vận hành cho đội Sales</p></div></div><div class="split-cards"><div class="mini-card"><span class="metric-label">01 · Chuẩn hóa</span><h3>Ghi nhận dự án đang chạy</h3><p class="muted">Bổ sung khách hàng, khu vực, vị trí, headcount và mô hình dịch vụ.</p><button class="text-btn" data-view="projects">Mở dự án →</button></div><div class="mini-card"><span class="metric-label">02 · Xác minh</span><h3>Cập nhật benchmark</h3><p class="muted">Lưu khoảng lương, mức phí, ngày cập nhật và nguồn tham khảo.</p><button class="text-btn" data-view="pricing">Mở bảng giá →</button></div><div class="mini-card"><span class="metric-label">03 · Phát triển</span><h3>Nuôi dưỡng lead</h3><p class="muted">Ghi nguồn tin tuyển dụng công khai, trạng thái và người phụ trách.</p><button class="text-btn" data-view="opportunities">Mở cơ hội →</button></div></div></div>`
}
function marketFinder(){const roles=['Phụ kho','Công nhân sản xuất','Lễ tân','CSKH','Telesales','CSKH tiếng Anh','CSKH tiếng Trung','CSKH tiếng Nhật','CSKH tiếng Hàn','Lao động phổ thông','Nhân viên kho','Back Office'];const regions=['Miền Bắc','Hà Nội','Hải Phòng','Bắc Ninh','Bắc Giang','Miền Trung','Đà Nẵng','Huế','Quảng Nam','Miền Nam','TP. Hồ Chí Minh','Củ Chi','Long An','Bình Dương','Đồng Nai','VSIP 1','VSIP 2','VSIP 3'];const industries=['E-commerce','Thương mại điện tử','Logistics','Ngân hàng','Banking','Finance','Tài chính','Warehouse','Kho vận','F&B','FMCG','Retail','Bán lẻ'];return `<section class="panel market-finder" id="marketFinder"><div class="panel-head"><div><div class="eyebrow">TRA CỨU 3 CHIỀU</div><h3>Vị trí công việc × Khu vực × Ngành nghề</h3><p>Tìm theo bất kỳ yếu tố nào; kết quả sẽ đồng thời cho biết hai yếu tố còn lại trong các dự án đang chạy.</p></div><span class="finder-mark">↔</span></div><div class="finder-grid"><label class="finder-field"><span>⌕ Vị trí công việc</span><input class="control" id="finderPosition" list="finderPositions" placeholder="Ví dụ: CSKH, kho, telesales…"><datalist id="finderPositions">${roles.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label class="finder-field"><span>⌖ Khu vực</span><input class="control" id="finderRegion" list="finderRegions" placeholder="Ví dụ: Bình Dương, miền Bắc…"><datalist id="finderRegions">${regions.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label class="finder-field"><span>▦ Ngành nghề / lĩnh vực</span><input class="control" id="finderIndustry" list="finderIndustries" placeholder="Ví dụ: Logistics, FMCG…"><datalist id="finderIndustries">${industries.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label></div><div class="finder-actions"><span class="cell-sub">Chỉ tính dự án có trạng thái “Đang chạy”; danh mục gợi ý không có nghĩa là đã có dự án.</span><button class="secondary-btn" id="clearMarketFinder">Xóa tìm kiếm</button></div><div id="marketFinderResults">${marketFinderResults()}</div></section>`}
function finderNorm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim()}
function marketFinderResults(){
const roleQ=finderNorm($('#finderPosition')?.value),regionQ=finderNorm($('#finderRegion')?.value),industryQ=finderNorm($('#finderIndustry')?.value);
const north=['ha noi','hai phong','bac ninh','bac giang'],central=['da nang','hue','quang nam'],south=['ho chi minh','tp ho chi minh','cu chi','long an','binh duong','dong nai','vsip'];
function regionMatches(record,q){if(!q)return true;const r=finderNorm([record.region,record.district,record.ward,record.notes].join(' '));if(r.includes(q))return true;const aliases={'mien bac':north,'mien trung':central,'mien nam':south,'tphcm':['ho chi minh','tp ho chi minh','cu chi'],'hcm':['ho chi minh','tp ho chi minh','cu chi'],'sai gon':['ho chi minh','tp ho chi minh','cu chi']};const list=aliases[q];return !!list&&list.some(x=>r.includes(finderNorm(x)))}
const records=[];
for(const p of db.projects)records.push({kind:'Dự án',type:'project',id:p.id,title:p.customer||p.name||p.id,position:p.positions||p.position||'',region:p.region||'',district:p.district||'',ward:p.ward||'',industry:p.industry||'',status:p.status||'Chưa xác định',headcount:p.headcount,notes:p.notes||'',raw:p});
for(const p of db.pricing)records.push({kind:'Benchmark vị trí/phí',type:'pricing',id:p.id,title:p.position||p.model||p.id,position:p.position||'',region:p.region||'',industry:p.industry||'',status:p.verified||'Chưa xác minh',headcount:'',notes:[p.model,p.source,p.notes].filter(Boolean).join(' '),raw:p});
for(const l of db.leads)records.push({kind:'Cơ hội',type:'lead',id:l.id,title:l.name||l.potential||l.id,position:l.potential||l.positions||'',region:l.region||'',industry:l.industry||'',status:l.status||'Chưa xác định',headcount:'',notes:[l.signal,l.notes].filter(Boolean).join(' '),raw:l});
for(const c of db.clients)records.push({kind:'Khách hàng',type:'client',id:c.id,title:c.name||c.id,position:c.services||c.positions||'',region:c.region||'',industry:c.industry||'',status:c.status||c.type||'Chưa xác định',headcount:'',notes:c.notes||'',raw:c});
const matches=records.filter(r=>{const roleText=finderNorm([r.position,r.title,r.notes].join(' ')),industryText=finderNorm([r.industry,r.notes].join(' '));return (!roleQ||roleText.includes(roleQ))&&regionMatches(r,regionQ)&&(!industryQ||industryText.includes(industryQ))});
const split=vals=>[...new Set(vals.flatMap(v=>String(v||'').split(/[,;\/|]+/).map(x=>x.trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'vi'));
const positions=split(matches.map(r=>r.position)),regions=split(matches.map(r=>[r.region,r.district,r.ward].filter(Boolean).join(' · '))),industries=split(matches.map(r=>r.industry));
const openButton=r=>`<button class="text-btn finder-open" data-finder-open="${r.type}" data-id="${esc(r.id)}">${esc(r.title)}</button>`;
return `<div class="finder-summary"><strong>${matches.length}</strong><span>hồ sơ liên quan trong dữ liệu đã nhập · dự án, benchmark, khách hàng và cơ hội</span></div><div class="finder-results-grid"><article class="finder-result"><div class="finder-result-head"><span>01</span><b>Vị trí công việc</b><small>${positions.length}</small></div>${positions.length?`<div class="finder-chips">${positions.map(x=>`<button class="finder-chip" data-finder-fill="position" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:'<p class="muted">Chưa có vị trí phù hợp.</p>'}</article><article class="finder-result"><div class="finder-result-head"><span>02</span><b>Khu vực có dữ liệu</b><small>${regions.length}</small></div>${regions.length?`<div class="finder-chips">${regions.map(x=>`<button class="finder-chip" data-finder-fill="region" data-value="${esc(x.split(' · ')[0])}">${esc(x)}</button>`).join('')}</div>`:'<p class="muted">Chưa có khu vực phù hợp.</p>'}</article><article class="finder-result"><div class="finder-result-head"><span>03</span><b>Ngành nghề / lĩnh vực</b><small>${industries.length}</small></div>${industries.length?`<div class="finder-chips">${industries.map(x=>`<button class="finder-chip" data-finder-fill="industry" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:'<p class="muted">Chưa có ngành nghề phù hợp.</p>'}</article></div>${matches.length?`<div class="table-wrap finder-table"><table><thead><tr><th>Loại hồ sơ / tên</th><th>Vị trí / dịch vụ</th><th>Khu vực</th><th>Ngành / lĩnh vực</th><th>Trạng thái</th></tr></thead><tbody>${matches.slice(0,100).map(r=>`<tr><td><div class="cell-sub">${esc(r.kind)} · ${esc(r.id)}</div>${openButton(r)}</td><td style="white-space:normal">${esc(r.position||'—')}</td><td>${esc([r.region,r.district,r.ward].filter(Boolean).join(' · ')||'—')}</td><td>${esc(r.industry||'—')}</td><td>${esc(r.status||'—')}</td></tr>`).join('')}</tbody></table></div>${matches.length>100?`<p class="cell-sub">Đang hiển thị 100 trên ${matches.length} hồ sơ phù hợp.</p>`:''}`:'<div class="empty-hint">Không tìm thấy hồ sơ phù hợp với các điều kiện. Thử xóa bớt điều kiện hoặc kiểm tra dữ liệu đã nhập ở Dự án, Khách hàng, Lương & phí dịch vụ và Cơ hội tiềm năng.</div>'}`
}
function updateMarketFinder(){const out=$('#marketFinderResults');if(out)out.innerHTML=marketFinderResults()}
function tableShell(head,rows,empty,cols){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${cols}" class="muted" style="text-align:center;padding:30px">${empty}</td></tr>`}</tbody></table></div>`}
function projectsPage(q){let list=db.projects.filter(x=>JSON.stringify(x).toLowerCase().includes(q));const wards=[...new Set(db.projects.map(x=>x.ward).filter(Boolean))].sort();return `<div class="section-head"><div><h2>Dự án & nhân sự</h2><p>Tra cứu theo tỉnh/thành, quận/huyện hoặc phường/xã, ngành và trạng thái dự án.</p></div><button class="primary-btn" data-add="project">＋ Thêm dự án</button></div><div class="toolbar">${regionFilter()}<select class="control" id="districtFilter"><option value="">Tất cả quận/huyện</option>${[...new Set(db.projects.map(x=>x.district).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="control" id="wardFilter"><option value="">Tất cả phường/xã</option>${wards.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="control" id="statusFilter"><option value="">Tất cả trạng thái</option><option>Đang chạy</option><option>Tạm dừng</option><option>Đã kết thúc</option></select><select class="control" id="industryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.projects.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="secondary-btn" id="clearProjectFilters">Xóa lọc</button></div><div id="projectTable">${projectRows(list)}</div><p class="cell-sub" style="margin-top:12px">${list.length} dự án · Bổ sung quận/huyện và phường/xã trong hồ sơ dự án để lọc chi tiết.</p>`}
function projectRows(list){return tableShell(['Khách hàng / dự án','Khu vực · Ngành','Vị trí cung cấp','Nhân sự','Lương tham khảo','Phí dịch vụ','Trạng thái',''],list.map(x=>`<tr><td><button class="project-open" data-project-detail="${esc(x.id)}"><span class="cell-main">${esc(x.customer)}</span><span class="cell-sub">${esc(x.id)} · ${esc(x.service)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc([x.district,x.ward].filter(Boolean).join(' · '))}</div><div class="cell-sub">${esc(x.industry)}</div></td><td style="max-width:230px;white-space:normal">${esc(x.positions)}</td><td class="price">${num(x.headcount)}</td><td class="price">${fmt(x.salary)}<div class="cell-sub">${esc(x.salaryUnit||'Theo tháng (VNĐ/tháng)')}</div></td><td class="price">${formatAmount(x.fee,x.feeUnit)}<div class="cell-sub">${esc(x.feeUnit||'VNĐ/người/tháng')}${x.taxRate!==''&&x.taxRate!=null?' · VAT '+esc(x.taxRate)+'%':''}</div></td><td>${statusPill(x.status)}</td><td><div class="row-actions"><button class="small-btn" data-edit="project" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="project" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''), 'Không tìm thấy dự án phù hợp.',8)}
function clientsPage(q){let list=db.clients.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Hồ sơ khách hàng</h2><p>Một hồ sơ cho mỗi doanh nghiệp, bao gồm khách hàng đang chạy và tài khoản mục tiêu.</p></div><button class="primary-btn" data-add="client">＋ Thêm khách hàng</button></div><div class="toolbar">${regionFilter()}<select class="control" id="typeFilter"><option value="">Tất cả nhóm</option><option>Khách hàng hiện tại</option><option>Khách hàng tiềm năng</option><option>Đối tác</option></select><select class="control" id="clientStatusFilter"><option value="">Tất cả trạng thái</option><option>Đang hợp tác</option><option>Đang tiếp cận</option><option>Cần nghiên cứu</option><option>Không phù hợp</option></select><button class="secondary-btn" id="clearClientFilters">Xóa lọc</button></div><div id="clientTable">${clientRows(list)}</div>`}
function clientRows(list){return tableShell(['Doanh nghiệp','Khu vực · Ngành','Nhóm khách hàng','Dịch vụ quan tâm','Liên hệ / Website','Trạng thái','Nguồn',''],list.map(x=>`<tr><td><button type="button" class="record-open" data-client-detail="${esc(x.id)}"><span class="cell-main">${esc(x.name)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td>${esc(x.type)}</td><td style="white-space:normal;max-width:190px">${esc(x.services)}</td><td>${esc(x.contact||'—')}${x.website?`<div class="cell-sub"><a class="source-link" href="${esc(x.website)}" target="_blank" rel="noopener">Website ↗</a></div>`:''}</td><td>${statusPill(x.status)}</td><td>${esc(x.source||'—')}</td><td><div class="row-actions"><button class="small-btn" data-edit="client" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="client" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có khách hàng phù hợp.',8)}
function pricingPage(q){let list=db.pricing.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Lương & phí dịch vụ</h2><p>So sánh chi phí nhân sự và giá bán dịch vụ theo vị trí, khu vực và mô hình BPO.</p></div><button class="primary-btn" data-add="pricing">＋ Thêm benchmark</button></div><div class="callout"><b>Lưu ý:</b> Các con số mẫu hiện tại chỉ để minh họa tính năng, không phải khảo sát thị trường đã xác minh. Mỗi benchmark thực tế nên có nguồn, ngày cập nhật và trạng thái xác minh.</div><div class="toolbar">${regionFilter()}<select class="control" id="verifiedFilter"><option value="">Mọi trạng thái nguồn</option><option>Đã xác minh</option><option>Chưa xác minh</option><option>Cần cập nhật</option></select><select class="control" id="pricingIndustryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.pricing.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><p id="filterResultCount">${list.length} kết quả</p><div id="pricingTable">${pricingRows(list)}</div>`}
function pricingRows(list){return tableShell(['Vị trí','Khu vực · Ngành','Khoảng lương','Phí dịch vụ','Mô hình dịch vụ','Nguồn / cập nhật','Xác minh',''],list.map(x=>`<tr><td><button type="button" class="record-open" data-pricing-detail="${esc(x.id)}"><span class="cell-main">${esc(x.position)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td class="price">${fmt(x.salaryMin)} – ${fmt(x.salaryMax)}<div class="cell-sub">${esc(x.salaryUnit||'Theo tháng (VNĐ/tháng)')}</div></td><td class="price">${formatAmount(x.feeMin,x.feeUnit)} – ${formatAmount(x.feeMax,x.feeUnit)}<div class="cell-sub">${esc(x.feeUnit||x.feeType||'VNĐ/người/tháng')}${x.taxRate!==''&&x.taxRate!=null?' · VAT '+esc(x.taxRate)+'%':''}</div></td><td>${esc(x.service)}</td><td>${x.sourceUrl?`<a class="source-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Mở nguồn ↗</a>`:esc(x.source||'—')}<div class="cell-sub">Cập nhật: ${esc(x.updated||'—')}</div></td><td>${statusPill(x.verified)}</td><td><div class="row-actions"><button class="small-btn" data-edit="pricing" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="pricing" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có benchmark phù hợp.',8)}
function leadsPage(q){let list=db.leads.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Cơ hội tiềm năng</h2><p>Ghi nhận doanh nghiệp mục tiêu, tín hiệu tuyển dụng công khai và bước tiếp theo của Sales.</p></div><button class="primary-btn" data-add="lead">＋ Thêm cơ hội</button></div><div class="callout"><b>Quy trình đề xuất:</b> Tìm nguồn công khai → lưu URL và ngày cập nhật → xác minh công ty/vị trí → ghi nhận người phụ trách → tiếp cận theo quy trình của công ty. Không thu thập dữ liệu cá nhân nhạy cảm hoặc nội dung riêng tư.</div><div class="toolbar">${regionFilter()}<select class="control" id="leadStatusFilter"><option value="">Tất cả trạng thái</option><option>Chưa tiếp cận</option><option>Cần xác minh</option><option>Đang tiếp cận</option><option>Đang đàm phán</option><option>Đã chuyển đổi</option><option>Không phù hợp</option></select><select class="control" id="leadIndustryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.leads.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="leadTable">${leadRows(list)}</div>`}
function leadRows(list){return tableShell(['Doanh nghiệp / mục tiêu','Khu vực · Ngành','Nhu cầu dự kiến','Tín hiệu / nguồn','Điểm ưu tiên','Sales phụ trách','Trạng thái',''],list.map(x=>`<tr><td><button type="button" class="record-open" data-lead-detail="${esc(x.id)}"><span class="cell-main">${esc(x.name)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button><div class="cell-sub">${x.sourceUrl?`<a class="source-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Mở nguồn ↗</a>`:esc(x.source||'Chưa có nguồn')}</div></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td style="white-space:normal;max-width:180px">${esc(x.potential)}</td><td style="white-space:normal;max-width:220px">${esc(x.signal)}<div class="cell-sub">Liên hệ: ${esc(x.contact||'Chưa cập nhật')}</div></td><td><span class="lead-score">${'★'.repeat(Math.max(0,Math.min(5,Number(x.score||0))))}${'☆'.repeat(5-Math.max(0,Math.min(5,Number(x.score||0))))}</span></td><td>${esc(x.owner||'Chưa phân công')}</td><td>${statusPill(x.status)}</td><td><div class="row-actions"><button class="small-btn" data-edit="lead" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="lead" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có cơ hội phù hợp.',8)}
function researchPage(){return `<div class="section-head"><div><h2>Nghiên cứu & survey thị trường</h2><p>Tạo truy vấn theo vị trí, khu vực và ngành; mở nguồn công khai để kiểm tra rồi lưu kết quả bằng tay vào cơ sở dữ liệu cục bộ.</p></div></div><div class="callout"><b>Cách dùng:</b> nhập thông tin cần khảo sát → mở các nguồn tìm kiếm → xác minh tin tuyển dụng, ngày đăng, địa điểm và đơn vị → lưu thông tin vào mục Lương & phí hoặc Cơ hội tiềm năng. App không tự đọc dữ liệu từ các trang bên ngoài; các nguồn có thể yêu cầu đăng nhập riêng.</div><form id="researchForm" class="research-form"><label>Từ khóa / vị trí<input name="query" required placeholder="Ví dụ: warehouse staff, customer service, telesales"></label><label>Khu vực<input name="region" placeholder="TP. Hồ Chí Minh, Bình Dương..."></label><label>Ngành<input name="industry" placeholder="Logistics, sản xuất, retail..."></label><button class="primary-btn" type="submit">⌕ Tạo khảo sát & mở nguồn</button></form><div id="researchStatus" class="callout" style="margin-top:16px">Không cần API key. App tạo các truy vấn tìm kiếm sẵn; bạn chọn nguồn, kiểm tra thông tin và nhập dữ liệu xác minh vào app.</div><div id="researchResults" class="research-grid"></div><h3 style="margin-top:26px">Nguồn khảo sát nhanh</h3><div class="research-grid">${[['Google','Tìm website doanh nghiệp và tin tuyển dụng'],['LinkedIn','Tìm trang công ty và tin tuyển dụng công khai'],['VietnamWorks','Tìm tin tuyển dụng theo vị trí'],['CareerViet','Tìm nhu cầu tuyển dụng tại Việt Nam'],['Indeed','Tìm vị trí đang tuyển'],['TopCV','Tìm tin tuyển dụng và mặt bằng vị trí']].map(x=>`<article class="research-result"><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><p class="cell-sub">Từ khóa được bổ sung khi bạn gửi khảo sát phía trên.</p></article>`).join('')}</div>`}
function settingsPage(){const st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');return `<div class="section-head"><div><h2>Cài đặt giao diện</h2><p>Tùy chỉnh màu chủ đạo, giao diện sáng/tối và cỡ chữ. Cài đặt được lưu trên thiết bị.</p></div></div><div class="settings-grid"><section class="setting-card"><h3>Chủ đề</h3><label for="themeSelect">Giao diện</label><select id="themeSelect" class="control"><option value="light" ${st.theme==='light'?'selected':''}>Sáng</option><option value="dark" ${st.theme==='dark'?'selected':''}>Tối</option><option value="auto" ${!st.theme||st.theme==='auto'?'selected':''}>Theo hệ thống</option></select><label for="fontSelect">Cỡ chữ</label><select id="fontSelect" class="control"><option value="15px" ${!st.font||st.font==='15px'?'selected':''}>Tiêu chuẩn</option><option value="16px" ${st.font==='16px'?'selected':''}>Lớn</option><option value="14px" ${st.font==='14px'?'selected':''}>Nhỏ</option></select></section><section class="setting-card"><h3>Màu chủ đạo</h3><p class="muted">Chọn màu phù hợp với phong cách làm việc.</p><div class="swatches">${['#16796f','#1769aa','#6941c6','#c05c2b','#b83d5a','#344054'].map(color=>`<button class="swatch ${((st.color||'#6941c6')===color)?'selected':''}" style="background:${color}" data-color="${color}" aria-label="Màu ${color}"></button>`).join('')}</div><button class="secondary-btn" id="resetSettings" style="margin-top:20px">Khôi phục mặc định</button></section></div><div class="callout" style="margin-top:16px">Ghi chú: giao diện và màu sắc được lưu cục bộ trong trình duyệt/thiết bị hiện tại.</div>`}
function applySettings(){const st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');const c=st.color||'#6941c6';document.documentElement.style.setProperty('--green',c);document.documentElement.style.setProperty('--accent',c);document.documentElement.style.setProperty('--accent-soft',`color-mix(in srgb, ${c} 12%, transparent)`);document.documentElement.style.setProperty('--accent-border',`color-mix(in srgb, ${c} 38%, transparent)`);document.documentElement.style.setProperty('--accent-strong',`color-mix(in srgb, ${c} 82%, #102b29)`);document.documentElement.style.setProperty('--accent-tint',`color-mix(in srgb, ${c} 8%, white)`);document.documentElement.style.setProperty('--accent-dark',`color-mix(in srgb, ${c} 48%, #102b29)`);document.documentElement.style.setProperty('--accent-mid',`color-mix(in srgb, ${c} 72%, #163d37)`);document.body.style.fontSize=st.font||'15px';const dark=st.theme==='dark'||(st.theme==='auto'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('theme-dark',!!dark);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.colorScheme=dark?'dark':'light'}
function dataPage(){return `<div class="section-head"><div><h2>Nhập / xuất Excel</h2><p>Tải template, cập nhật dữ liệu trong Excel rồi upload để nhập vào database cục bộ.</p></div></div><div class="callout"><b>Quy trình an toàn:</b> tải template → giữ nguyên tên cột ở dòng đầu → nhập dữ liệu → upload file .xlsx. App sẽ xem trước số dòng và kiểm tra dữ liệu trước khi nhập. Bản nhập sẽ bổ sung bản ghi, không tự xóa dữ liệu đang có.</div><div class="data-actions"><button class="primary-btn" id="downloadTemplate">⇩ Tải template Excel</button><button class="secondary-btn" id="exportExcel">Xuất dữ liệu hiện tại (.xlsx)</button></div><section class="panel"><h3>Upload file Excel</h3><p class="muted">Hỗ trợ file template của app và tự nhận diện bảng dữ liệu có sẵn với các cột Khu vực, Lĩnh vực của KH, Tên Dự án (tên KH), Vị trí nhân sự, Phí dịch vụ. File CSV dùng được offline.</p><div class="dropzone"><p>Chọn file Excel đã cập nhật (.xlsx)</p><input type="file" id="excelFile" aria-label="Chọn tệp Excel hoặc CSV" accept=".xlsx,.xls,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"></div><div id="excelPreview" style="margin-top:14px"></div><button class="primary-btn" id="commitExcel" disabled>Kiểm tra và nhập dữ liệu</button></section><div class="panel" style="margin-top:16px"><h3>Cấu trúc sheet</h3><p><b>Projects:</b> customer, region, industry, status, positions, headcount, service, salary, salaryUnit, fee, feeUnit, taxRate, updated, notes</p><p><b>Clients:</b> name, region, industry, type, status, website, sourceUrl, notes</p><p><b>SalaryFees:</b> position, region, industry, salaryMin, salaryMax, salaryUnit, feeMin, feeMax, feeUnit, taxRate, model, service, source, sourceUrl, verified, updated, notes. Dùng cho lao động phổ thông, sản xuất, kho vận, vệ sinh, bảo vệ, giao nhận, CSKH, telesales, back office và IT.</p><p><b>Leads:</b> name, region, industry, potential, signal, source, sourceUrl, contact, owner, score, status, updated, notes</p></div>`}
let pendingExcel=null;
function csvCell(v){const s=String(v??'');return '"'+s.replace(/"/g,'""')+'"'}
function downloadBlob(name,blob){if(window.AndroidDownloads&&typeof window.AndroidDownloads.saveFile==='function'){const reader=new FileReader();reader.onload=()=>{try{const b64=String(reader.result).split(',')[1]||'';window.AndroidDownloads.saveFile(name,blob.type||'application/octet-stream',b64)}catch(e){showToast('Không thể mở hộp thoại lưu tệp: '+(e.message||e))}};reader.onerror=()=>showToast('Không đọc được dữ liệu để lưu tệp.');reader.readAsDataURL(blob);return}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},10000)}
function downloadText(name,text,type='text/csv;charset=utf-8'){downloadBlob(name,new Blob(['\ufeff',text],{type}))}
function downloadXlsx(wb,name){const mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';if(window.AndroidDownloads&&window.XLSX){window.AndroidDownloads.saveFile(name,mime,XLSX.write(wb,{bookType:'xlsx',type:'base64'}));return}const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});downloadBlob(name,new Blob([bytes],{type:mime}))}
function downloadBundledTemplate(){if(window.AndroidDownloads&&typeof window.AndroidDownloads.saveBundledTemplate==='function'){window.AndroidDownloads.saveBundledTemplate();return}fetch('assets/BPO-Intelligence-Hub-Excel-Template.xlsx').then(r=>{if(!r.ok)throw Error('Không tải được template tích hợp');return r.blob()}).then(b=>downloadBlob('BPO-Intelligence-Hub-Excel-Template.xlsx',b)).catch(()=>{downloadText('BPO-Template.csv','table,field,example\r\nProjects,customer,Ten doanh nghiep\r\nProjects,region,TP. Ho Chi Minh\r\nProjects,industry,Logistics\r\nProjects,status,Dang chay\r\nProjects,positions,CSKH; Back Office\r\nClients,name,Ten doanh nghiep\r\nClients,region,Ha Noi\r\nSalaryFees,position,Nhan vien kho\r\nSalaryFees,region,Binh Duong\r\nSalaryFees,industry,Logistics\r\nLeads,name,Ten co hoi\r\nLeads,region,Da Nang\r\nLeads,industry,Sản xuất');showToast('Không truy cập được file XLSX tích hợp; đã tạo template CSV thay thế.')})}
function rowsToCsv(rows){const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];return [keys.map(csvCell).join(','),...rows.map(r=>keys.map(k=>csvCell(r[k])).join(','))].join('\r\n')}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(quoted){if(c==='"'&&n==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell.length||row.length){row.push(cell);if(row.some(x=>x.trim()))rows.push(row)}if(rows.length<2)throw Error('CSV phải có hàng tiêu đề và ít nhất một hàng dữ liệu.');const headers=rows.shift().map(x=>x.trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??'']))).filter(r=>Object.values(r).some(v=>String(v).trim()))}
function importHeaderKey(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function findImportColumn(headers,aliases){const norm=headers.map(h=>[h,importHeaderKey(h)]);for(const alias of aliases){const a=importHeaderKey(alias);const exact=norm.find(x=>x[1]===a);if(exact)return exact[0]}for(const alias of aliases){const a=importHeaderKey(alias);if(a.length>3){const partial=norm.find(x=>x[1].includes(a)||a.includes(x[1]));if(partial)return partial[0]}}return null}
function parseImportedMoney(value){if(value===null||value===undefined||value==='')return '';if(typeof value==='number')return value;const raw=String(value).trim();const m=raw.match(/[-+]?\d[\d.,\s]*/);if(!m)return '';let n=m[0].replace(/\s/g,'');const comma=n.lastIndexOf(','),dot=n.lastIndexOf('.');if(comma>=0&&dot>=0){const dec=Math.max(comma,dot);const tail=n.length-dec-1;if(tail>0&&tail<=2){const whole=n.slice(0,dec).replace(/[.,]/g,'');n=whole+'.'+n.slice(dec+1)}else n=n.replace(/[.,]/g,'')}else if(comma>=0){const tail=n.length-comma-1;n=tail>0&&tail<=2?n.replace(/\./g,'').replace(',','.'):n.replace(/,/g,'')}else if(dot>=0){const tail=n.length-dot-1;n=tail>0&&tail<=2?n.replace(/,/g,''):n.replace(/[.,]/g,'')}const num=Number(n);return Number.isFinite(num)?num:''}
function importedFeeUnit(value){const t=importHeaderKey(value);if(t.includes('ngay')||t.includes('day'))return 'VNĐ/người/ngày';if(t.includes('gio')||t.includes('hour'))return 'VNĐ/người/giờ';if(t.includes('thang')||t.includes('month'))return 'VNĐ/người/tháng';if(t.includes('%'))return '% lương tháng';return 'Phí cố định/lần'}
function smartImportRows(rows){if(!rows.length)return null;const headers=Object.keys(rows[0]||{});const cols={region:findImportColumn(headers,['Khu vực','Region','Địa bàn','Địa điểm']),industry:findImportColumn(headers,['Lĩnh vực của KH','Lĩnh vực khách hàng','Ngành nghề','Ngành','Industry','Lĩnh vực']),customer:findImportColumn(headers,['Tên Dự án (tên KH)','Tên dự án','Tên khách hàng','Khách hàng','Doanh nghiệp','Customer','Project name']),position:findImportColumn(headers,['Vị trí nhân sự','Vị trí công việc','Vị trí','Chức danh','Position','Job title']),fee:findImportColumn(headers,['Phí Dịch vụ – năm gần nhất','Phí dịch vụ năm gần nhất','Phí dịch vụ','Service fee','Fee','Đơn giá dịch vụ']),year:findImportColumn(headers,['Năm','Năm phí','Year'])};if(!cols.region||!cols.industry||!cols.customer||!cols.position)return null;const projects=[],clients=[],pricing=[];const seenClients=new Set(),seenProjects=new Set(),seenPricing=new Set();for(const row of rows){const val=k=>String(cols[k]?row[cols[k]]??'':'').trim();const region=val('region'),industry=val('industry'),customer=val('customer'),positionRaw=val('position'),feeRaw=val('fee'),year=val('year')||(String(feeRaw).match(/20\d{2}/)||[])[0]||'';if(!customer&&!positionRaw)continue;const positions=[...new Set(positionRaw.split(/\r?\n|\s*;\s*|\s*\|\s*/).map(x=>x.trim()).filter(Boolean))];const projectKey=[customer,region,industry,positions.join('|')].map(importHeaderKey).join('~');if(customer&&!seenProjects.has(projectKey)){seenProjects.add(projectKey);projects.push({id:'',customer,region,industry,status:'Cần xác minh',positions:positions.join('\n'),headcount:'',service:'BPO / cung ứng nhân sự',salary:'',salaryUnit:'Theo tháng (VNĐ/tháng)',fee:parseImportedMoney(feeRaw),feeUnit:importedFeeUnit(feeRaw),taxRate:'',updated:today(),notes:`Nhập tự động từ dữ liệu có sẵn${year?' · dữ liệu phí năm '+year:''}. Cần xác minh trạng thái dự án và đơn vị tính.`})}const clientKey=importHeaderKey(customer);if(customer&&!seenClients.has(clientKey)){seenClients.add(clientKey);clients.push({id:'',name:customer,region,industry,type:'Khách hàng tiềm năng',status:'Cần nghiên cứu',website:'',source:'File dữ liệu do người dùng cung cấp',sourceUrl:'',updated:today(),notes:'Được nhập tự động từ bảng dữ liệu hiện có; cần xác minh quan hệ khách hàng và trạng thái hợp tác.'})}for(const pos of positions){const fee=parseImportedMoney(feeRaw),unit=importedFeeUnit(feeRaw);const key=[pos,region,industry,fee,unit].map(importHeaderKey).join('~');if(seenPricing.has(key))continue;seenPricing.add(key);pricing.push({id:'',position:pos,region,industry,salaryMin:'',salaryMax:'',salaryUnit:'Theo tháng (VNĐ/tháng)',feeMin:fee,feeMax:fee,feeUnit:unit,taxRate:'',model:'Phí dịch vụ lịch sử',service:'BPO / cung ứng nhân sự',source:'File dữ liệu do người dùng cung cấp',sourceUrl:'',verified:'Cần xác minh',updated:today(),notes:`Phí nguồn gốc: ${feeRaw||'không có'}${year?' · năm '+year:''}. Đã tự nhận diện cột; xác minh đơn vị và phạm vi phí trước khi dùng làm benchmark.`})}}if(!projects.length&&!clients.length&&!pricing.length)return null;return {data:{projects,clients,pricing},kind:'smart',sourceRows:rows.length}}
function standardizeImportRows(rows,key){return rows.map(r=>{const out={};for(const [k,v] of Object.entries(r)){const nk=importHeaderKey(k).replace(/\s/g,'');out[k]=v}return out})}
function setupDataPage(){const down=$('#downloadTemplate');if(down)down.onclick=()=>{if(!window.XLSX){downloadBundledTemplate();showToast('Đang chuẩn bị template. Hãy chọn nơi lưu tệp nếu được hỏi.');return}const wb=XLSX.utils.book_new();const sheets={Projects:[['customer','region','industry','status','positions','headcount','service','salary','salaryUnit','fee','feeUnit','taxRate','updated','notes'],['Ví dụ - Công ty giả lập','TP. Hồ Chí Minh','BPO - CSKH','Đang chạy','Customer Service, Back Office',20,'Outsourcing nhân sự','','Theo tháng (VNĐ/tháng)','','VNĐ/người/tháng','10',today(),'DÒNG MẪU - thay bằng dữ liệu thật']],Clients:[['name','region','industry','type','status','website','sourceUrl','notes'],['Ví dụ - Doanh nghiệp giả lập','Hà Nội','Logistics','Khách hàng tiềm năng','Cần nghiên cứu','','','DÒNG MẪU - thay bằng dữ liệu thật']],SalaryFees:[['position','region','industry','salaryMin','salaryMax','salaryUnit','feeMin','feeMax','feeUnit','taxRate','model','service','source','sourceUrl','verified','updated','notes'],['Nhân viên kho / đóng gói','Bình Dương','Logistics / Kho vận','','','Theo tháng (VNĐ/tháng)','','','VNĐ/người/tháng','10','Lương gross/tháng','Thuê ngoài nhân sự','Tin tuyển dụng công khai','https://www.google.com/search?q=tuy%E1%BB%83n+nh%C3%A2n+vi%C3%AAn+kho+B%C3%ACnh+D%C6%B0%C6%A1ng','Cần xác minh',today(),'DÒNG MẪU - cập nhật mức lương/phí sau khi xác minh; có thể dùng cho lao động phổ thông, CSKH, bảo vệ, vệ sinh, sản xuất, giao nhận.']],Leads:[['name','region','industry','potential','signal','source','sourceUrl','contact','owner','score','status','updated','notes'],['Ví dụ - Lead giả lập','Đà Nẵng','Sản xuất','BPO - Back Office','Có tin tuyển dụng công khai','Website công ty','https://example.com','','',3,'Cần xác minh',today(),'DÒNG MẪU - thay bằng dữ liệu thật']]};for(const [n,rows] of Object.entries(sheets))XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),n);downloadXlsx(wb,'BPO-Intelligence-Hub-Excel-Template.xlsx')};const ex=$('#exportExcel');if(ex)ex.onclick=()=>{if(!window.XLSX){downloadText('BPO-Intelligence-Hub-Export-'+today()+'.csv',rowsToCsv([{table:'Projects',records:JSON.stringify(db.projects)},{table:'Clients',records:JSON.stringify(db.clients)},{table:'SalaryFees',records:JSON.stringify(db.pricing)},{table:'Leads',records:JSON.stringify(db.leads)}]));showToast('Đã xuất một tệp CSV chứa dữ liệu sao lưu dạng JSON theo từng bảng.');return}const wb=XLSX.utils.book_new();for(const [name,key] of [['Projects','projects'],['Clients','clients'],['SalaryFees','pricing'],['Leads','leads']])XLSX.utils.json_to_sheet(db[key].length?db[key]:[{note:'Chưa có dữ liệu'}])&&XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(db[key].length?db[key]:[{note:'Chưa có dữ liệu'}]),name);downloadXlsx(wb,'BPO-Intelligence-Hub-Export-'+today()+'.xlsx')};const file=$('#excelFile');if(file)file.onchange=async()=>{pendingExcel=null;$('#commitExcel').disabled=true;$('#excelPreview').innerHTML='';const f=file.files[0];if(!f)return;try{let data={},total=0,smart=false,sourceRows=[];if(f.name.toLowerCase().endsWith('.csv')){sourceRows=parseCsv(await f.text());const first=sourceRows[0]||{};const map={Projects:'projects',Clients:'clients',SalaryFees:'pricing',Leads:'leads'};const sheetKey=Object.keys(map).find(k=>Object.keys(first).some(h=>h.toLowerCase()===k.toLowerCase()));if(sheetKey){data[map[sheetKey]]=sourceRows;total=sourceRows.length}else{const mapped=smartImportRows(sourceRows);if(mapped){data=mapped.data;smart=true;total=sourceRows.length}else{const firstKey=Object.keys(first)[0]||'';const target=({'customer':'projects','name':'clients','position':'pricing','potential':'leads'}[firstKey]);if(!target)throw Error('Không nhận diện được cột. Cần có tối thiểu Khu vực, Lĩnh vực của KH, Tên Dự án (tên KH), Vị trí nhân sự; hoặc dùng template của app.');data[target]=sourceRows;total=sourceRows.length}}}else{if(!window.XLSX)throw Error('Không có thư viện đọc .xlsx khi offline. Hãy xuất sheet cần nhập thành CSV UTF-8 hoặc kết nối Internet.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});const map={Projects:'projects',Clients:'clients',SalaryFees:'pricing',Leads:'leads'};for(const [sheet,key] of Object.entries(map)){if(wb.Sheets[sheet]){data[key]=XLSX.utils.sheet_to_json(wb.Sheets[sheet],{defval:''}).filter(r=>Object.values(r).some(v=>String(v).trim()));total+=data[key].length}}if(!total){const candidate=wb.SheetNames.map(name=>({name,rows:XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:''}).filter(r=>Object.values(r).some(v=>String(v).trim()))})).find(x=>x.rows.length);if(candidate){const mapped=smartImportRows(candidate.rows);if(mapped){data=mapped.data;smart=true;total=candidate.rows.length}}}}if(!total)throw Error('Không tìm thấy dòng dữ liệu. Với Excel theo cấu trúc riêng, hãy bảo đảm có tiêu đề cột và tối thiểu Khu vực, Lĩnh vực của KH, Tên Dự án, Vị trí nhân sự.');pendingExcel={data,smart};const counts=Object.entries(data).map(([k,v])=>`${({projects:'Dự án',clients:'Khách hàng',pricing:'Vị trí / phí',leads:'Cơ hội'}[k]||k)}: ${v.length}`).join(' · ');$('#excelPreview').innerHTML=`<div class="callout"><b>Đọc được ${total} dòng nguồn.</b><br>${counts}${smart?'<br><br><b>Đã tự nhận diện cấu trúc file.</b> Mỗi dòng có thể tạo/cập nhật dữ liệu dự án, khách hàng và benchmark vị trí/phí. Các bản ghi mới được đánh dấu “Cần xác minh”; hãy kiểm tra trước khi sử dụng.':'<br>Đã nhận diện cấu trúc template của ứng dụng.'}</div>`;$('#commitExcel').disabled=false}catch(e){$('#excelPreview').innerHTML=`<div class="callout">Không đọc được file: ${esc(e.message||'lỗi không xác định')}. Hãy kiểm tra hàng tiêu đề hoặc xuất sheet sang CSV UTF-8.</div>`}};const commit=$('#commitExcel');if(commit)commit.onclick=()=>{if(!pendingExcel)return;const defs={projects:['P','customer'],clients:['C','name'],pricing:['R','position'],leads:['L','name']};let added=0,skipped=0;for(const [key,rows] of Object.entries(pendingExcel.data)){for(const row of rows){const clean={};for(const [k,v] of Object.entries(row))clean[k]=v;const primary=defs[key][1];const match=pendingExcel.smart&&db[key].find(x=>importHeaderKey(x[primary])===importHeaderKey(clean[primary])&&importHeaderKey(x.region)===importHeaderKey(clean.region)&&(key!=='pricing'||importHeaderKey(x.position)===importHeaderKey(clean.position)));if(match){Object.assign(match,clean,{id:match.id,updated:today()});skipped++;continue}if(!clean.id||db[key].some(x=>String(x.id)===String(clean.id)))clean.id=defs[key][0]+'-IMP-'+String(Date.now()+added).slice(-8);if(!clean.updated)clean.updated=today();db[key].push(clean);added++}}save();pendingExcel=null;render();setupDataPage();showToast(`Đã nhập ${added} bản ghi${skipped?`; cập nhật ${skipped} bản ghi trùng`:''}.`)};}

function showDetailRecord(title,fields,type,id){const body=$('#detailBody');if(!body||!$('#detailBackdrop')){showToast('Không mở được cửa sổ chi tiết. Hãy tải lại ứng dụng.');return}$('#detailTitle').textContent=title;body.innerHTML=`<div class="detail-grid">${fields.filter(([k,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`<div class="detail-item"><span>${esc(k)}</span><strong>${esc(String(v??'—'))}</strong></div>`).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="detailClose">Đóng</button>${type&&id?`<button class="primary-btn" id="detailEdit" data-edit="${esc(type)}" data-id="${esc(id)}">Sửa thông tin</button>`:''}</div>`;$('#detailBackdrop').classList.remove('hidden');const close=()=>$('#detailBackdrop').classList.add('hidden');$('#detailClose').onclick=close;$('#detailX').onclick=close;$('#detailBackdrop').onclick=e=>{if(e.target===$('#detailBackdrop'))close()};const edit=$('#detailEdit');if(edit)edit.onclick=e=>{e.stopPropagation();close();openForm(type,id)}}
function showProjectDetail(id){const x=db.projects.find(p=>p.id===id);if(!x)return;showDetailRecord('Chi tiết dự án',[['Khách hàng / dự án',x.customer],['Mã dự án',x.id],['Khu vực',x.region],['Quận / huyện',x.district],['Phường / xã',x.ward],['Ngành / lĩnh vực',x.industry],['Trạng thái',x.status],['Vị trí cung cấp',x.positions],['Số lượng nhân sự',x.headcount],['Mô hình dịch vụ',x.service],['Lương tham khảo',moneyUnit(x.salary,x.salaryUnit)],['Đơn vị lương',x.salaryUnit],['Phí dịch vụ',moneyUnit(x.fee,x.feeUnit)],['Đơn vị phí dịch vụ',x.feeUnit],['Thuế / VAT',x.taxRate===''||x.taxRate==null?'Chưa cập nhật':`${Number(x.taxRate).toLocaleString('vi-VN',{maximumFractionDigits:2})}%`],['Cập nhật',x.updated],['Ghi chú',x.notes]],'project',id)}
function showLeadDetail(id){const x=db.leads.find(p=>p.id===id);if(!x)return;showDetailRecord('Chi tiết cơ hội tiềm năng',[['Doanh nghiệp / mục tiêu',x.name],['Mã cơ hội',x.id],['Khu vực',x.region],['Ngành / lĩnh vực',x.industry],['Nhu cầu / vị trí dự kiến',x.potential],['Tín hiệu thị trường',x.signal],['Nguồn',x.source],['URL nguồn',x.sourceUrl],['Thông tin liên hệ',x.contact],['Sales phụ trách',x.owner],['Điểm ưu tiên',x.score],['Trạng thái',x.status],['Ngày cập nhật',x.updated],['Ghi chú',x.notes]],'lead',id)}
function showClientDetail(id){const x=db.clients.find(p=>p.id===id);if(!x)return;showDetailRecord('Chi tiết khách hàng',[['Tên doanh nghiệp',x.name],['Mã khách hàng',x.id],['Khu vực',x.region],['Ngành / lĩnh vực',x.industry],['Nhóm khách hàng',x.type],['Dịch vụ quan tâm',x.services],['Người liên hệ',x.contact],['Website',x.website],['Nguồn',x.source],['URL nguồn',x.sourceUrl],['Trạng thái',x.status],['Ngày cập nhật',x.updated],['Ghi chú',x.notes]],'client',id)}
function showPricingDetail(id){const x=db.pricing.find(p=>p.id===id);if(!x)return;showDetailRecord('Chi tiết vị trí / benchmark',[['Vị trí công việc',x.position],['Mã benchmark',x.id],['Khu vực',x.region],['Ngành / lĩnh vực',x.industry],['Lương tối thiểu',moneyUnit(x.salaryMin,x.salaryUnit)],['Lương tối đa',moneyUnit(x.salaryMax,x.salaryUnit)],['Đơn vị lương',x.salaryUnit],['Phí dịch vụ tối thiểu',moneyUnit(x.feeMin,x.feeUnit)],['Phí dịch vụ tối đa',moneyUnit(x.feeMax,x.feeUnit)],['Đơn vị phí dịch vụ',x.feeUnit],['Thuế / VAT',x.taxRate===''||x.taxRate==null?'Chưa cập nhật':`${Number(x.taxRate).toLocaleString('vi-VN',{maximumFractionDigits:2})}%`],['Mô hình / cơ sở tính',x.model],['Mô hình dịch vụ',x.service],['Nguồn',x.source],['URL nguồn',x.sourceUrl],['Trạng thái xác minh',x.verified],['Ngày cập nhật',x.updated],['Ghi chú',x.notes]],'pricing',id)}


const REGION_OPTIONS=['Miền Bắc','Hà Nội','Hải Phòng','Bắc Ninh','Bắc Giang','Hưng Yên','Vĩnh Phúc','Miền Trung','Đà Nẵng','Huế','Quảng Nam','Quảng Ngãi','Miền Nam','TP. Hồ Chí Minh','HCM','Củ Chi','Long An','Bình Dương','Đồng Nai','Bà Rịa - Vũng Tàu','Tây Ninh','VSIP 1','VSIP 2','VSIP 3','Toàn quốc','Vùng I','Vùng II','Vùng III','Vùng IV'];
const INDUSTRY_OPTIONS=['E-commerce / Thương mại điện tử','Logistics / Kho vận','Sản xuất','Ngân hàng','Tài chính / Bảo hiểm','F&B / Nhà hàng - thực phẩm','FMCG / Hàng tiêu dùng nhanh','Bán lẻ / Retail','BPO / Vận hành','Dịch vụ khách hàng','Bán hàng','Facility Management','An ninh','Y tế / Chăm sóc sức khỏe','Giáo dục','Công nghệ thông tin','Viễn thông','Du lịch / Khách sạn','Bất động sản','Chính sách lao động','Khác'];
function choiceOptions(key,value){const defaults=key==='region'?REGION_OPTIONS:INDUSTRY_OPTIONS;const currentValues=Object.values(db).flat().map(x=>x?.[key]).filter(Boolean);return [...new Set([...defaults,...currentValues,...(value?[value]:[])])].sort((a,b)=>{const ai=defaults.indexOf(a),bi=defaults.indexOf(b);if(ai>=0&&bi>=0)return ai-bi;if(ai>=0)return -1;if(bi>=0)return 1;return a.localeCompare(b,'vi')})}
function openForm(type,id){const sc=schemas[type];editing={type,id};const item=id?db[sc.key].find(x=>x.id===id):{};$('#modalTitle').textContent=(id?'Sửa ':'Thêm ')+sc.label;$('#formFields').innerHTML=sc.fields.map(f=>{const [key,label,kind,extra]=f;let value=item?.[key]??(key==='updated'?today():key==='score'?'3':key==='salaryUnit'?'Theo tháng (VNĐ/tháng)':key==='feeUnit'?'VNĐ/người/tháng':'');let input='';if(key==='region'||key==='industry'){const opts=choiceOptions(key,value);const isKnown=opts.includes(String(value));input=`<select name="${key}" class="control" data-custom-select="${key}" required><option value="">Chọn ${key==='region'?'khu vực':'ngành / lĩnh vực'}...</option>${opts.map(o=>`<option value="${esc(o)}" ${String(value)===o?'selected':''}>${esc(o)}</option>`).join('')}<option value="__other__">＋ Khác (nhập mới)</option></select><input class="custom-choice-input ${!isKnown&&value?'':'hidden'}" name="${key}__custom" value="${!isKnown?esc(value):''}" placeholder="Nhập ${key==='region'?'khu vực':'ngành / lĩnh vực'} mới" ${!isKnown&&value?'required':''}>`;}else if(kind==='select')input=`<select name="${key}" class="control" required><option value="">Chọn...</option>${extra.map(o=>`<option ${String(value)===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(kind==='textarea')input=`<textarea name="${key}" ${extra===1?'':' '}>${esc(value)}</textarea>`;else if(kind==='decimal')input=`<input name="${key}" type="text" inputmode="decimal" data-decimal="true" value="${esc(value)}" ${['salary','fee','salaryMin','salaryMax','feeMin','feeMax','taxRate'].includes(key)?'minlength="0"':''} placeholder="Nhập số, ví dụ 12500000 hoặc 125,5">`;else input=`<input name="${key}" type="${kind}" value="${esc(value)}" ${['customer','name','position','region'].includes(key)?'required':''} ${kind==='number'?'min="0" step="any"':''} placeholder="${kind==='url'?'https://...':''}">`;return `<div class="field ${extra===1?'full':''}"><label>${esc(label)}</label>${input}</div>`}).join('');$('#modalBackdrop').classList.remove('hidden');setTimeout(()=>$('#formFields input')?.focus(),30)}
function closeForm(){$('#modalBackdrop').classList.add('hidden');editing=null}
$('#dataForm').addEventListener('submit',e=>{e.preventDefault();if(!editing)return;const {type,id}=editing,sc=schemas[type],data=Object.fromEntries(new FormData(e.currentTarget).entries());for(const key of ['region','industry']){if(data[key]==='__other__'){data[key]=String(data[key+'__custom']||'').trim();if(!data[key]){showToast('Vui lòng nhập tên mới.');return}}delete data[key+'__custom'];}for(const f of sc.fields){const key=f[0];if(f[2]==='number')data[key]=data[key]===''?'':Number(data[key]);if(f[2]==='decimal')data[key]=parseDecimal(data[key]);}if(!data.updated)data.updated=today();if(id){const idx=db[sc.key].findIndex(x=>x.id===id);db[sc.key][idx]={...db[sc.key][idx],...data}}else{const prefix={project:'P',client:'C',pricing:'R',lead:'L'}[type];data.id=prefix+'-'+String(Date.now()).slice(-6);db[sc.key].unshift(data)}save();closeForm();render();showToast(id?'Dữ liệu đã được cập nhật.':'Đã thêm dữ liệu mới.');});
function deleteRecord(type,id){const sc=schemas[type];const x=db[sc.key].find(r=>r.id===id);if(!x)return;if(confirm(`Xóa “${x.customer||x.name||x.position}”? Thao tác này không thể hoàn tác.`)){db[sc.key]=db[sc.key].filter(r=>r.id!==id);save();render();showToast('Đã xóa bản ghi.')}}
function normFilter(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').trim().toLocaleLowerCase('vi-VN')}
function filteredList(type){const sc=schemas[type],q=normFilter($('#globalSearch')?.value||'');let a=db[sc.key].filter(x=>!q||normFilter(JSON.stringify(x)).includes(q));const region=$('#regionFilter')?.value||'';if(region){const r=normFilter(region);a=a.filter(x=>normFilter(x.region)===r)}const district=$('#districtFilter')?.value||'';if(district)a=a.filter(x=>normFilter(x.district)===normFilter(district));const ward=$('#wardFilter')?.value||'';if(ward)a=a.filter(x=>normFilter(x.ward)===normFilter(ward));const filterIds={project:['statusFilter','status'],client:['typeFilter','type'],pricing:['verifiedFilter','verified'],lead:['leadStatusFilter','status']};const pair=filterIds[type];if(pair){const v=$('#'+pair[0])?.value;if(v)a=a.filter(x=>normFilter(x[pair[1]])===normFilter(v))}const indId={project:'industryFilter',pricing:'pricingIndustryFilter',lead:'leadIndustryFilter'}[type];if(indId){const v=$('#'+indId)?.value;if(v)a=a.filter(x=>normFilter(x.industry)===normFilter(v))}if(type==='client'){const v=$('#clientStatusFilter')?.value;if(v)a=a.filter(x=>normFilter(x.status)===normFilter(v))}return a}
function refreshFiltered(){let id={projects:'project',clients:'client',pricing:'pricing',opportunities:'lead'}[view];if(!id){if($('#pricingTable'))id='pricing';else if($('#projectTable'))id='project';else if($('#clientTable'))id='client';else if($('#leadTable'))id='lead'}if(!id)return;const list=filteredList(id);const dest={project:'#projectTable',client:'#clientTable',pricing:'#pricingTable',lead:'#leadTable'}[id];const target=$(dest);if(!target)return;target.innerHTML={project:projectRows,client:clientRows,pricing:pricingRows,lead:leadRows}[id](list);const count=$('#filterResultCount');if(count)count.textContent=`${list.length} kết quả`}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-project-detail]');if(detail){showProjectDetail(detail.dataset.projectDetail);return}const clientDetail=e.target.closest('[data-client-detail]');if(clientDetail){showClientDetail(clientDetail.dataset.clientDetail);return}const pricingDetail=e.target.closest('[data-pricing-detail]');if(pricingDetail){showPricingDetail(pricingDetail.dataset.pricingDetail);return}const leadDetail=e.target.closest('[data-lead-detail]');if(leadDetail){showLeadDetail(leadDetail.dataset.leadDetail);return}const color=e.target.closest('[data-color]');if(color){const st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');st.color=color.dataset.color;localStorage.setItem('bpo-ui-settings',JSON.stringify(st));applySettings();render();return}const v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);if(view==='data')setupDataPage();return}const add=e.target.closest('[data-add]');if(add){openForm(add.dataset.add);return}const edit=e.target.closest('[data-edit]');if(edit){openForm(edit.dataset.edit,edit.dataset.id);return}const del=e.target.closest('[data-delete]');if(del){deleteRecord(del.dataset.delete,del.dataset.id);return}});
document.addEventListener('input',e=>{if(['finderPosition','finderRegion','finderIndustry'].includes(e.target.id))updateMarketFinder()});document.addEventListener('click',e=>{const open=e.target.closest('[data-finder-open]');if(open){const id=open.dataset.id;const type=open.dataset.finderOpen;if(type==='project')showProjectDetail(id);else if(type==='client')showClientDetail(id);else if(type==='pricing')showPricingDetail(id);else if(type==='lead')showLeadDetail(id);return}const chip=e.target.closest('[data-finder-fill]');if(chip){const id={position:'finderPosition',region:'finderRegion',industry:'finderIndustry'}[chip.dataset.finderFill];const field=$('#'+id);if(field){field.value=chip.dataset.value;updateMarketFinder()}return}if(e.target.id==='clearMarketFinder'){['finderPosition','finderRegion','finderIndustry'].forEach(id=>{const el=$('#'+id);if(el)el.value=''});updateMarketFinder()}});function navigateBack(){const modal=$('#modalBackdrop'),detail=$('#detailBackdrop'),sidebar=$('#sidebar');if(modal&&!modal.classList.contains('hidden')){closeForm();return true}if(detail&&!detail.classList.contains('hidden')){detail.classList.add('hidden');return true}if(sidebar?.classList.contains('open')){closeMenu();return true}if(viewHistory.length){const previous=viewHistory.pop();view=previous;$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const t={overview:'Tổng quan thị trường',projects:'Dự án & nhân sự',clients:'Hồ sơ khách hàng',pricing:'Lương & phí dịch vụ',opportunities:'Cơ hội tiềm năng',research:'Nghiên cứu thị trường',data:'Excel & dữ liệu',settings:'Cài đặt'};$('#pageTitle').textContent=t[view];$('#crumb').textContent=view==='overview'?'SALES COMMAND CENTER':'BPO INTELLIGENCE / '+t[view].toUpperCase();render();if(view==='data')setupDataPage();return true}if(view!=='overview'){view='overview';viewHistory=[];$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageTitle').textContent='Tổng quan thị trường';$('#crumb').textContent='SALES COMMAND CENTER';render();return true}return false}
window.handleAppBack=navigateBack;$('#backBtn').addEventListener('click',()=>{navigateBack()});document.addEventListener('click',e=>{if(e.target.id==='clearProjectFilters'||e.target.id==='clearClientFilters'){const ids=view==='clients'?['regionFilter','typeFilter','clientStatusFilter']:['regionFilter','districtFilter','wardFilter','statusFilter','industryFilter'];ids.forEach(id=>{const el=$('#'+id);if(el)el.value=''});refreshFiltered();showToast('Đã xóa bộ lọc.');return}});
document.addEventListener('change',e=>{if(e.target.matches('[data-custom-select]')){const key=e.target.dataset.customSelect,custom=e.target.parentElement.querySelector(`[name=\"${key}__custom\"]`);if(custom){const show=e.target.value==='__other__';custom.classList.toggle('hidden',!show);custom.required=show;if(show){custom.value='';custom.focus()}else custom.value='';}return}const filterIds=['regionFilter','districtFilter','wardFilter','statusFilter','industryFilter','typeFilter','clientStatusFilter','verifiedFilter','pricingIndustryFilter','leadStatusFilter','leadIndustryFilter'];if(filterIds.includes(e.target.id)){refreshFiltered();return}if(e.target.id==='themeSelect'||e.target.id==='fontSelect'){const st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');if(e.target.id==='themeSelect')st.theme=e.target.value;else st.font=e.target.value;localStorage.setItem('bpo-ui-settings',JSON.stringify(st));applySettings();showToast('Đã lưu cài đặt.')}});document.addEventListener('click',e=>{if(e.target.id==='resetSettings'){localStorage.removeItem('bpo-ui-settings');applySettings();render();showToast('Đã khôi phục mặc định.')}});$('#quickAdd').addEventListener('click',()=>openForm(({overview:'project',projects:'project',clients:'client',pricing:'pricing',opportunities:'lead'})[view]||'project'));$('#closeModal').addEventListener('click',closeForm);$('#cancelModal').addEventListener('click',closeForm);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeForm()});$('#globalSearch').addEventListener('input',render);function closeMenu(){$('#sidebar').classList.remove('open');$('#mobileNavBackdrop')?.classList.remove('visible');$('#menuBtn').setAttribute('aria-expanded','false')}function openMenu(){const isOpen=$('#sidebar').classList.toggle('open');$('#mobileNavBackdrop')?.classList.toggle('visible',isOpen);$('#menuBtn').setAttribute('aria-expanded',String(isOpen))}$('#menuBtn').addEventListener('click',openMenu);$('#mobileNavBackdrop')?.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')navigateBack()});let swipeStart=null;document.addEventListener('touchstart',e=>{if(e.touches.length!==1)return;const t=e.touches[0];swipeStart={x:t.clientX,y:t.clientY,edge:t.clientX<48||t.clientX>window.innerWidth-48};},{passive:true});document.addEventListener('touchend',e=>{if(!swipeStart||!e.changedTouches.length)return;const t=e.changedTouches[0],dx=t.clientX-swipeStart.x,dy=t.clientY-swipeStart.y,edge=swipeStart.edge;swipeStart=null;if(dx>85&&Math.abs(dy)<70&&edge&&t.clientX>85){navigateBack()}},{passive:true});$('#exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString(),app:'BPO Intelligence Hub',schemaVersion:1},null,2)],{type:'application/json;charset=utf-8'});downloadBlob('bpo-intelligence-backup-'+today()+'.json',blob);showToast('Đang lưu bản sao lưu. Hãy chọn thư mục lưu tệp nếu được hỏi.');});$('#importBtn').addEventListener('click',()=>$('#importFile').click());$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const d=JSON.parse(await file.text());if(!['projects','clients','pricing','leads'].every(k=>Array.isArray(d[k])))throw Error('invalid');if(confirm('Nhập bản sao lưu sẽ thay thế dữ liệu hiện tại trên thiết bị. Bạn muốn tiếp tục?')){db={projects:d.projects,clients:d.clients,pricing:d.pricing,leads:d.leads};save();render();showToast('Đã nhập bản sao lưu.')}}catch(err){showToast('File không hợp lệ. Hãy chọn bản sao lưu JSON từ app.')}e.target.value=''});

// Navigation uses the delegated click handler above to avoid duplicate view changes.
function searchUrl(base,query){return base+encodeURIComponent(query)}
document.addEventListener('submit',e=>{if(e.target.id!=='researchForm')return;e.preventDefault();const fd=new FormData(e.target);const query=String(fd.get('query')||'').trim(),region=String(fd.get('region')||'').trim(),industry=String(fd.get('industry')||'').trim();const terms=[query,region,industry].filter(Boolean).join(' ');const general=terms+' tuyển dụng OR hiring OR outsourcing OR salary';const sources=[['Google · Tổng quan','https://www.google.com/search?q=',general],['Google · Tin tuyển dụng','https://www.google.com/search?q=',terms+' site:vietnamworks.com OR site:careerviet.vn OR site:topcv.vn'],['LinkedIn · Công ty','https://www.linkedin.com/search/results/companies/?keywords=',terms],['LinkedIn · Việc làm','https://www.linkedin.com/jobs/search/?keywords=',terms],['VietnamWorks','https://www.google.com/search?q=',terms+' site:vietnamworks.com'],['CareerViet','https://www.google.com/search?q=',terms+' site:careerviet.vn'],['TopCV','https://www.google.com/search?q=',terms+' site:topcv.vn'],['Indeed','https://www.google.com/search?q=',terms+' site:vn.indeed.com']];const out=$('#researchResults');out.innerHTML=sources.map((x,i)=>`<article class="research-result"><h3>${esc(x[0])}</h3><p>${esc(x[2])}</p><a href="${esc(searchUrl(x[1],x[2]))}" target="_blank" rel="noopener">Mở nguồn ↗</a><div style="margin-top:12px"><button class="small-btn" data-save-research="${i}" data-query="${esc(x[2])}" data-region="${esc(region)}" data-industry="${esc(industry)}" data-source="${esc(x[0])}">Lưu truy vấn vào ghi chú</button></div></article>`).join('');$('#researchStatus').textContent='Đã tạo '+sources.length+' truy vấn. Kết quả mở trên các nền tảng bên ngoài; hãy xác minh nguồn trước khi sử dụng.';window.bpoResearchQueries=sources.map(x=>({title:x[0],query:x[2],region,industry}));});
document.addEventListener('click',e=>{const b=e.target.closest('[data-save-research]');if(!b)return;const q=b.dataset.query||'';db.leads.unshift({id:'L-'+String(Date.now()).slice(-6),name:'Khảo sát: '+q.slice(0,90),region:b.dataset.region||'',industry:b.dataset.industry||'',potential:'Cần xác minh vị trí / dịch vụ',signal:'Truy vấn nghiên cứu đã lưu. Mở nguồn, ghi nhận doanh nghiệp, mức lương, ngày đăng và URL cụ thể sau khi xác minh.',source:b.dataset.source||'Tìm kiếm công khai',sourceUrl:'',contact:'Chưa tìm',owner:'',score:2,status:'Cần xác minh',updated:today(),notes:'Truy vấn: '+q+'\nChỉ là ghi chú nghiên cứu, chưa phải kết quả thị trường đã xác minh.'});save();showToast('Đã lưu truy vấn vào Cơ hội tiềm năng.');setView('opportunities');});
